// This module loads icons.json (generated by scripts/build-icons.mjs before build)
// and exposes the same helper functions the original Cloudflare Worker used.
import iconsData from "./icons.json";

const icons: Record<string, string> = iconsData as Record<string, string>;

export const iconNameList: string[] = [
  ...new Set(Object.keys(icons).map((i) => i.split("-")[0])),
];

export const themedIcons: string[] = Object.keys(icons)
  .filter((i) => i.includes("-light") || i.includes("-dark"))
  .map((i) => i.split("-")[0]);

