const ICONS_PER_LINE = 15;
const ONE_ICON = 48;
const SCALE = ONE_ICON / (300 - 44);

export function generateSvg(iconNames: string[], perLine: number): string {
  const iconSvgList = iconNames.map((i) => icons[i]);

  const length = Math.min(perLine * 300, iconNames.length * 300) - 44;
  const height = Math.ceil(iconSvgList.length / perLine) * 300 - 44;
  const scaledHeight = height * SCALE;
  const scaledWidth = length * SCALE;

  return `<svg width="${scaledWidth}" height="${scaledHeight}" viewBox="0 0 ${length} ${height}" fill="none" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" version="1.1">
  ${iconSvgList
    .map(
      (i, index) =>
        `<g transform="translate(${(index % perLine) * 300}, ${
          Math.floor(index / perLine) * 300
        })">${i}</g>`
    )
    .join("\n  ")}
</svg>`;
}

export function parseShortNames(
  names: string[],
  theme: "dark" | "light" = "dark"
): (string | undefined)[] {
  return names.map((name) => {
    if (iconNameList.includes(name))
      return name + (themedIcons.includes(name) ? `-${theme}` : "");
    else if (name in shortNames)
      return (
        shortNames[name] +
        (themedIcons.includes(shortNames[name]) ? `-${theme}` : "")
      );
    return undefined;
  });
}

export { ICONS_PER_LINE, icons };